describe('Error Boundary - UI Crash Handling', () => {
  beforeEach(() => {
    cy.visit('/dashboard');
  });

  it('should display fallback screen when an error occurs in a component', () => {
    // Intercept the API call that might cause a crash
    cy.intercept('GET', '/api/data').as('apiData');

    // Trigger the API call
    cy.wait('@apiData');

    // Simulate a crash in the component by forcing an error
    cy.get('[data-testid="crash-component"]').then((crashComponent) => {
      crashComponent.then((element) => {
        element.click();
        cy.stub(window, 'console', {
          error: (message) => {
            cy.log('Error: ' + message);
          }
        }).as('consoleStub');

        // Force a crash by accessing a non-existent property
        cy.get('@crash-component').then((crashElement) => {
          crashElement.then((element) => {
            element.prop('nonExistentProperty');
          });
        });
      });
    });

    // Verify fallback screen is displayed
    cy.get('[data-testid="fallback-screen"]').should('be.visible');
    cy.get('[data-testid="fallback-screen"]').should('contain', 'Oops, something went wrong');
    cy.get('[data-testid="fallback-screen"]').should('have.class', 'error-boundary-fallback');
  });

  it('should not display fallback screen when error is caught by error boundary', () => {
    // Intercept the API call
    cy.intercept('GET', '/api/data').as('apiData');

    // Trigger the API call
    cy.wait('@apiData');

    // Simulate a crash in a component
    cy.get('[data-testid="crash-component"]').then((crashComponent) => {
      crashComponent.then((element) => {
        element.click();
        cy.stub(window, 'console', {
          error: (message) => {
            cy.log('Error: ' + message);
          }
        }).as('consoleStub');

        // Force a crash
        cy.get('@crash-component').then((crashElement) => {
          crashElement.then((element) => {
            element.prop('nonExistentProperty');
          });
        });
      });
    });

    // Verify error boundary catches the crash and does not show fallback
    cy.get('[data-testid="crash-component"]').should('be.visible');
    cy.get('[data-testid="error-boundary-fallback"]').should('not.exist');
    cy.get('[data-testid="error-boundary-fallback"]').should('not.be.visible');
    cy.get('[data-testid="error-boundary-message"]').should('be.visible');
    cy.get('[data-testid="error-boundary-message"]').should('contain', 'An unexpected error occurred');
  });
});
